-- Nạp quiz chuẩn bị tối trước BUỔI 9 (CNC lớp đảo ngược): 5 câu, đọc trước Bài 6 · mục 4.
-- Soạn từ content/lesson-samples/cnc-bai-6-gia-cong-tien — Bài 6 Gia công tiện (mục 4 Tiện côn, tiện ren).
-- Không ghi đè nếu thầy đã đăng prep-9 qua /quan-tri/cnc-dang-de (on conflict do nothing).
-- Lưu ý: trigger trg_exams_sync_bank chép câu vào question_bank như mọi ngân hàng CNC khác.
-- Rollback: delete from public.exams where cnc_key = 'prep-9';
insert into public.exams (title, duration_minutes, published, questions, topic, difficulty, cnc_key)
values ('Chuẩn bị buổi 9 — Gia công tiện (2)', 20, false, '[{"type": "multiple_choice", "question": "Côn có đầu to D = 40 mm, đầu nhỏ d = 30 mm, dài L = 50 mm. Độ côn C là:", "options": ["1:5", "1:10", "1:4", "5:1"], "answer": 0, "explanation": "Mục 4: C = (D − d)/L = 10/50 = 1/5, viết 1:5. 1:10 là nhầm chia 2 (đó là tan α)."}, {"type": "multiple_choice", "question": "Nửa góc côn α (góc giữa đường côn và trục) tính bằng:", "options": ["tan α = (D − d)/L", "tan α = (D + d)/(2L)", "tan α = (D − d)/(2L)", "tan α = L/(D − d)"], "answer": 2, "explanation": "Mục 4: tan α = (D − d)/(2L). (D − d)/L là độ côn C, chưa chia 2 vì D, d là đường kính."}, {"type": "multiple_choice", "question": "Tiện ren M16×2. Mỗi vòng trục chính, dao tiến dọc trục Z bao nhiêu?", "options": ["2 mm", "16 mm", "1,2 mm", "1 mm"], "answer": 0, "explanation": "Mục 4: M16×2 có đường kính danh nghĩa 16, bước P = 2 mm; mỗi vòng dao tiến đúng một bước P. 1,2 mm là chiều sâu ren."}, {"type": "multiple_choice", "question": "Ren M16×2, chiều sâu ren theo bán kính khoảng 0,6P. Đường kính chân ren khoảng:", "options": ["Ø14,8", "Ø14,0", "Ø13,6", "Ø12,0"], "answer": 2, "explanation": "Mục 4: sâu ≈ 0,6 × 2 = 1,2 mm; X là đường kính nên chân ren ≈ 16 − 2 × 1,2 = 13,6. Ø14,8 là quên nhân 2."}, {"type": "multiple_choice", "question": "Vì sao tiện ren phải cắt nhiều lượt, mỗi lượt nông dần?", "options": ["Để tăng tốc độ trục chính giữa các lượt", "Vì bước ren thay đổi sau mỗi lượt", "Để máy có thời gian đồng bộ dao với trục chính", "Cắt một nhát thì lực cắt lớn, dao dễ gãy, ren bị xé"], "answer": 3, "explanation": "Mục 4 (Xem thêm): một nhát ăn cả rãnh ren nên lực cắt lớn; chia lượt nông dần giữ lực vừa phải. Khi tiện ren giữ nguyên n."}]'::jsonb, 'CNC', '', 'prep-9')
on conflict (cnc_key) do nothing;
